CREATE TABLE messenger_pairings(id TEXT PRIMARY KEY,page_id TEXT NOT NULL,credential_id TEXT NOT NULL,secret_hash TEXT NOT NULL,expected_hash TEXT NOT NULL,expires_at INTEGER NOT NULL,claimed_hash TEXT,claimed_cipher TEXT,claimed_at INTEGER,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','claimed','confirmed','revoked')));
CREATE TABLE messenger_admin_links(slot INTEGER PRIMARY KEY CHECK(slot=1),page_id TEXT NOT NULL,credential_id TEXT NOT NULL,psid_hash TEXT NOT NULL,psid_cipher TEXT NOT NULL,created_at INTEGER NOT NULL,revoked_at INTEGER);
CREATE TABLE messenger_admin_jobs(id TEXT PRIMARY KEY,page_id TEXT NOT NULL,psid_hash TEXT NOT NULL,command_cipher TEXT NOT NULL,result_cipher TEXT,inbound_at INTEGER NOT NULL,delivery_state TEXT NOT NULL DEFAULT 'pending' CHECK(delivery_state IN('pending','sending','sent','blocked','unknown')),delivery_error TEXT,state TEXT NOT NULL DEFAULT 'pending' CHECK(state IN('pending','processing','done','cancelled')),created_at INTEGER NOT NULL);
CREATE TABLE messenger_admin_actions(id TEXT PRIMARY KEY,page_id TEXT NOT NULL,psid_hash TEXT NOT NULL,item_id TEXT NOT NULL,status TEXT NOT NULL,expected_updated_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,state TEXT NOT NULL DEFAULT 'pending' CHECK(state IN('pending','consumed','cancelled')));
CREATE INDEX messenger_pairing_page_expiry ON messenger_pairings(page_id,expires_at);
CREATE INDEX messenger_admin_job_page_state ON messenger_admin_jobs(page_id,state,created_at);
